-- GENERATED by `wfi generate` from data/quest/quest-0003.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [3000] = { nil, "Parla con Tiza Battleforge, a Ironforge.", "Salve, {name}. So che sei <impegnato/impegnata> ad aiutare la gente di Azeroth, ma quando avrai tempo dovresti tornare a Ironforge e parlare con una delle paladine più rispettate della tua terra: Tiza Battleforge. È da lei che vanno i giovani paladini nanici quando è tempo di imparare di più sulla Luce e su ciò che ci si aspetta da tutti noi.\n\nLa trovi al piano di sopra, nella Hall of Mysteries, che si trova nel Mystic Ward.", nil, "Ti saluto e ti do il benvenuto, {name}.", nil, 0x04be03fc, 0x3dc4f4ac, nil, 0x35f6641b, "m..m." },
  [3001] = { "Alla ricerca di Strahad", nil, nil, nil, nil, 0x884bfbbe, nil, nil, nil, nil, ".mmmm" },
  [3100] = { nil, "Leggi la Simple Letter e parla con Llane Beshere nella Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Llane, il nostro istruttore dei guerrieri. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ah, hai ricevuto la mia lettera, {name}... bene.\n\nUltimamente sono arrivati parecchi guerrieri a Elwynn: un bene per Stormwind, ma un male per i kobold e i Defias della zona.", "Sistemati per bene, impara a conoscere il territorio e torna da me ogni volta che hai bisogno di addestramento. Sarò qui giorno e notte.\n\nI Knights of the Silver Hand hanno fatto un buon lavoro per rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno qualche problema per cui servirebbe una mano: una mano che proprio tu, come {class}, puoi dar loro. Buona fortuna.", nil, 0xcd1a2f24, 0xfe579234, 0x76e67b55, 0x1ce50385, "m...." },
  [3101] = { nil, "Leggi la Consecrated Letter e parla con Brother Sammuel nella Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Brother Sammuel, il nostro istruttore dei paladini. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Finalmente! Ci incontriamo faccia a faccia, da fratello a <fratello/sorella>. Ti do il benvenuto a Northshire. Questa sarà la tua casa per un po', mentre impari come vanno le cose, ma sappi che Stormwind non è lontana e prima o poi il tuo cammino ti porterà là. Fino ad allora, sii paziente... Knight of the Silver Hand.", "Nel frattempo, dovresti sapere un paio di cose. Per molti, in questa terra, sei un simbolo: comportati di conseguenza. La Sacra Luce splende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.\n\nInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando sentirai di aver fatto un po' di esperienza qui a Northshire, torna da me e ti insegnerò ciò che penso tu sia <pronto/pronta> a imparare. Buona fortuna... {class}!", nil, 0x6d6ee593, 0x26cd99ad, 0xeb1b3e11, 0x8b941ae4, "m....", nil, nil, nil, 0x808f8fbe, nil },
  [3102] = { nil, "Leggi l'Encrypted Letter e parla con Jorik Kerridan nella stalla dietro la Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Jorik, uno dei nostri istruttori. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ce l'hai fatta ad arrivare fin qui senza un graffio, e non sembra che ti abbiano visto in molti. Per me basta così. Non mi piace attirare troppa attenzione qui dietro... bello tranquillo. Sono sicuro che capisci.\n\nHai già avuto problemi? Bene, mi fa piacere. Presto le cose cambieranno.", "Scoprirai che parecchie organizzazioni ambiscono alle nostre abilità, {name}. Avventurieri, SI:7... diamine, perfino la Defias Brotherhood non disdegnerebbe una spia o due dentro Stormwind. Ma ricordati questo: nessuno decide per te. Non lasciare che qualcuno ti costringa a fare qualcosa che non vuoi! E poi, tutte le carte le abbiamo in mano noi... almeno finché la partita non è finita. Capisci cosa intendo?\n\nComunque, volevo solo presentarmi e farti sapere che sono qui se hai bisogno di addestramento. Passa quando vuoi.", nil, 0x3d129a05, 0xb39f75e7, 0x6b9b0e24, 0xd57ec303, "m....", nil, nil, nil, nil, 0x46913652 },
  [3103] = { nil, "Leggi la Hallowed Letter e parla con Priestess Anetta nella Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Priestess Anetta, la nostra istruttrice dei sacerdoti. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ah, finalmente eccoti. Sapevo che avresti trovato la strada fino a me. La Sacra Luce splende su di te e sul cammino che hai scelto. Sono tempi duri: la Burning Legion è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e spetta a te aiutare quante più persone puoi.", "Man mano che acquisirai esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore, e lascia che la saggezza ti guidi. Ricorda: il mondo diventa un posto migliore solo se sei tu a renderlo tale.", nil, 0x3719f745, 0x63ba8573, 0x3c6b09ac, 0x69805596, "m...." },
  [3104] = { nil, "Leggi la Glyphic Letter e parla con Khelden Bremen dentro la Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Khelden, il nostro istruttore dei maghi. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Salve, {name}. Sono Khelden. Posso fare qualcosa per te?", "Ah ah, sapevo che il mio biglietto non ti avrebbe distolto dal tuo cammino. Quindi sei <pronto/pronta>, vero? <Pronto/Pronta> ad accettare il tuo destino? <Pronto/Pronta> a sfidare gli dei e qualsiasi altra forza ti si pari davanti nella ricerca del sapere e del potere?\n\nNon ti mentirò, {name}: sarai <temuto/temuta> quanto <rispettato/rispettata>. Ma sappi anche questo: io sarò qui per te quando avrai bisogno di addestramento. Basta che tu mi cerchi man mano che diventi più potente.", nil, 0xb2702f67, 0xde444377, 0x1257130c, 0xea282e3b, "m...." },
  [3105] = { nil, "Leggi la Tainted Letter e parla con Drusilla La Salle accanto alla Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Drusilla, una delle nostre istruttrici. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ah, eccoti qui, e appena in tempo, {name}. Poco fa alcune guardie erano qui e mi guardavano con curiosità... patetici profani.", "Man mano che il tuo potere cresce, sarai <tentato/tentata>: devi sempre ricordarti di controllarti. Non ti mentirò: la corruzione può colpire chiunque pratichi l'arcano, soprattutto chi ha a che fare con le creature del Twisting Nether. Sii paziente e prudente... ma non lasciare che questo soffochi la tua ambizione.\n\nQuando sarai più potente, torna da me e ti insegnerò di più sulle nostre vie.", nil, 0xa2b9450e, 0xc0471a03, 0x04538110, 0x1fcadfe2, "m...." },
  [3106] = { nil, "Leggi la Simple Rune e parla con Thran Khorman, a Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei guerrieri Thran. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Accidenti che freddo oggi, eh? Sembra che la neve non se ne vada mai, {name}.\n\nL'avrai già notato, ma ora in città vivono degli gnomi. È perché si sono fatti saltare in aria la loro stessa casa. Non andarlo a dire in giro, ma non posso fargliene una colpa: credo che anch'io sarei ricorso agli esplosivi se Ironforge fosse infestata dai Dark Iron o simili.", "Altre cose che probabilmente vedrai, giusto perché tu sia al corrente: nani che in battaglia usano la magia invece del fucile. Alcuni di noi che si mettono a venerare la Sacra Luce come certi umani e, ultimo ma non meno importante, i trogg. Su di loro imparerai di più più avanti, ma quel che devi sapere ora è che sono qui per aiutarti.\n\nSono qui per insegnarti a essere un vero {class}. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.", nil, 0xa8e2a12b, 0x0b2a8f18, 0x45cd211f, 0xc0004879, "m...." },
  [3107] = { nil, "Leggi la Consecrated Rune e parla con Bromos Grummner, a Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei paladini Bromos. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Allora ce l'hai fatta! E appena in tempo. C'è molto da fare a Coldridge Valley e oltre. Avrò bisogno del tuo aiuto quanto tu avrai bisogno del mio!\n\nOra sei un Knight of the Silver Hand: preparati a recitare la parte.", "Gli umani ci hanno insegnato molto sulla Sacra Luce e su quanto il loro ordine sia importante per loro... e per la protezione di tutta Azeroth. Abbiamo grande rispetto per quanto sia intriso di tradizione, e per come una sola figura, un solo sacrificio, possa fare la differenza tra dolore e salvezza.\n\nNoi due lavoreremo insieme per un po'. Ogni volta che pensi di essere <pronto/pronta>, torna da me e vedremo di farti addestrare. Non possiamo lasciarti andare per il mondo <impreparato/impreparata>, no?", nil, 0x95f50fa0, 0x01726882, 0x5259d37c, 0x8df035d1, "m...." },
  [3108] = { nil, "Leggi l'Etched Rune e parla con Thorgas Grimson, a Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei cacciatori Thorgas. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai nemmeno dovuto seguire le mie tracce per trovare il posto. Ahah!\n\nLa nostra professione è intrisa di tradizione, {name}. Imparare le vie della terra. Imparare a seguire le tracce di un orso tra le montagne. Anche solo sopravvivere con il proprio ingegno richiede molto coraggio e astuzia. Pensi di esserne capace?", "Una cosa che devi sempre ricordare è che devi rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco, la lucentezza della tua arma, il peso delle tue munizioni, il morso di un vento gelido: devi conoscere a fondo tutte queste cose.\n\nFarò il possibile per aiutarti, ma gran parte del lavoro spetta a te. Ogni volta che pensi di essere <pronto/pronta>, torna a parlarmi. Ti addestrerò quando posso.", nil, 0xaa004bc7, 0x3f424343, 0x919eafc7, 0x04729792, "m...." },
  [3109] = { nil, "Leggi l'Encrypted Rune e parla con Solm Hargrin, a Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei ladri Solm. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Ce l'hai fatta! Ottimo!\n\nUltimamente c'è un gran via vai, quindi sono contento di contare un altro membro del clan di Ironforge tra le nostre file. Troppi di noi si rivolgono all'arcano e al divino, per i miei gusti. Niente contro di loro e le loro credenze, ma non c'è niente come una lama fredda in mano e un'ombra che ti tenga lontano dalla luce, capisci cosa intendo?", "Comunque, quando comincerai a curiosare per Coldridge, prima o poi avrai bisogno di addestramento. Torna da me ogni volta che ne senti il bisogno e ti insegnerò quel che so: un trucco qui, una manovra là. Sai, la roba che ti tiene in vita e ti fa guadagnare qualche moneta in più.\n\nE tieni d'occhio i nostri amici gnomeschi... a loro è andata piuttosto male, con Gnomeregan... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.", nil, 0x5ff77ee1, 0xfc6f1297, 0xdfb79b4e, 0x81c5d183, "m...." },
  [3110] = { nil, "Leggi l'Hallowed Rune e parla con Branstock Khalder, ad Anvilmar.", "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei sacerdoti Branstock. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Ah! Ce l'hai fatta, {name}! Magnifico!\n\nStavo per dire che stavo per perdere la fede che saresti mai <arrivato/arrivata>... capito, perdere la fede? È una battuta, <ragazzo/ragazza>... ah, lascia perdere. Tanto non sei <venuto/venuta> qui per le mie pessime battute.", "Sono io quello che può addestrarti mentre impari a orientarti per Coldridge Valley. Quando ti senti <pronto/pronta>, torna da me e vedremo di insegnarti un incantesimo o due per difendere la valle da quei maledetti trogg.\n\nHai la Luce dalla tua parte, insieme a tutta Ironforge, {name}... nessuna pressione perché tu diventi qualcuno di speciale.", nil, 0x2feef57d, 0xa512f166, 0x054b980d, 0x2b1b31d2, "m...." },
  [3112] = { nil, "Leggi il Simple Memorandum e parla con Thran Khorman, a Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questo promemoria da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei guerrieri Thran. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Ah, beh, un altro promemoria da parte di un membro della razza {race} in missione... che pittoresco.\n\nNo, no, non ti sto prendendo in giro, <piccoletto/piccoletta>. Devo rispettare la tua tenacia, questo è certo. Sarei altrettanto seccato se Ironforge fosse stata presa dai nani Dark Iron, quindi non pensare che non comprenda la tua difficile situazione...", "Beh, visto che questa è la tua direttiva principale, o come la chiamate di questi tempi, ho dato la mia parola che avrei fatto il possibile perché tu e i tuoi foste pronti a riprendervi la vostra casa... ed è proprio quello che farò.\n\nOgni volta che ti senti <pronto/pronta>, torna dal buon vecchio Thran e sarò felice di condividere con te quel che so. Il mio addestramento ha un costo, ma non sarà troppo caro. Buona fortuna.", nil, 0xfd32d41c, 0xc7252d3e, 0x2813cf41, 0x954e3497, "m...." },
  [3113] = { nil, "Leggi l'Encrypted Memorandum e parla con Solm Hargrin, a Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questo promemoria da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei ladri Solm. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Sono contento di vedere che hai ricevuto il mio biglietto e sei <venuto/venuta>. Scusa se ho finto che fosse un promemoria dei tuoi superiori... senza offesa. Sapevo solo che noi due, insieme ad altri come noi, dobbiamo restare uniti.\n\nNon in molti pensano che sia la cosa migliore del mondo avere la tua gente e la mia rintanate nella stessa città, ma credo che possiamo andare d'accordo benissimo. Tu che ne pensi?", "Qui me ne sto per lo più per conto mio, così non ci danno la colpa per le cose che spariscono, ma se ti serve qualcosa, un po' di addestramento o altro, torna quando vuoi.\n\nTu e io ci capiamo. Sappiamo che, alla fine dei conti, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Nonostante Gnomeregan sia stata... invasa, e qualunque altra cosa ci capiti, possiamo contare l'uno sull'altro. Giusto?", nil, 0xadca2176, 0xddd66e3c, 0x6c381354, 0x094ba3b2, "m...." },
  [3114] = { nil, "Leggi il Glyphic Memorandum e parla con Marryk Nurribit, dentro Anvilmar, sopra Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questo promemoria da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei maghi Marryk. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.", "Sì, cos'è, {race}? Parla più forte, se non ti dispiace. Dopo qualche birra non ci sento tanto bene.", "Oh, già! Le arti arcane... certo.\n\nEcco cosa devi sapere, {name}: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per qualsiasi incantesimo tu voglia. E stai alla larga da Gnomeregan, accidenti. A parte questo, buona giornata! Sarò qui se hai bisogno di me o vuoi addestrarti... o quel che è.", nil, 0x442b0781, 0x8ec02c25, 0x2a6a6bb4, 0xf605ca24, "m...." },
  [3115] = { nil, "Leggi il Tainted Memorandum e parla con Alamar Grimm, dentro Anvilmar, sopra Coldridge Valley.", "Mentre mi davi una mano, mi hanno consegnato questo promemoria da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei stregoni Alamar. Dagli un'occhiata e va' a cercarlo dentro Anvilmar quando puoi.\n\nE sta' in guardia, {name}: quelli come te non godono di molta fiducia da queste parti.", "Magnifico! Evidentemente hai ricevuto il mio promemoria.\n\nIgnora gli sciocchi intorno a te, {name}. La Sacra Luce?! Spada e scudo?! Non sono sentieri per menti aperte come le nostre. Guarda cosa ha fatto la magia \"normale\" alla nostra casa. Insieme a quei maledetti inventori, la nostra razza si è quasi estinta. E ora dobbiamo affidarci ai nani, che preferiscono passare il tempo ad allearsi con gli umani piuttosto che aiutarci a ricostruire la nostra casa. Siamo come cittadini di seconda classe. Hai visto come ci guardano?", "Ma niente di tutto questo conta. Quel che conta è che hai visto la tua Sacra Luce! Sai da dove viene davvero il potere. Capisci che avere alleati propri è molto più... prudente. Alleati speciali. Alleati che, qualunque sia il compito, obbediranno fino all'ultimo respiro.\n\nEd è qui che entro in gioco io, {name}. Posso insegnarti i primi rudimenti di quei poteri speciali. Cercami spesso e farò il possibile per insegnarti nuovi incantesimi.", nil, 0xc0e37525, 0x9cf6a18f, 0xefc765ed, 0x0c6a5847, "m...." },
  [3116] = { nil, "Leggi il Simple Sigil e parla con Alyissia, a Shadowglen.", "Questo sigillo me l'ha dato un messaggero della nostra istruttrice dei guerrieri, Alyissia. Sembra che Alyissia voglia parlarti quando hai un momento. Leggilo e poi portaglielo.", "Ce l'hai fatta. Ne sono così felice.\n\nMolte cose sono successe negli ultimi anni, {name}: la creazione di Teldrassil, la corruzione di molte creature della foresta qui e altrove, la scoperta di terre che credevamo perdute per noi, come Feralas... tanto, in così poco tempo. Ma questi sono solo alcuni dei motivi per cui siamo qui: il più importante è proteggere la nostra gente da altro male.", "Presto vedrai altri, di razze diverse, tra i rami della nostra casa: non lasciare che questo faccia nascere in te dei pregiudizi. Sono i benvenuti. Ci aiuteranno quando potranno. Non tutti saranno altruisti, ma meritano un po' di fiducia.\n\nMa ora niente di tutto questo importa. Ora dobbiamo concentrarci su di te e su come puoi aiutare il nostro popolo. Sono qui proprio per questo. Ti addestrerò nelle vie del {class} man mano che diventerai più forte. Torna da me quando vuoi e farò il possibile per aiutarti.", nil, 0xd0e81f4b, 0xba14907e, 0x57568a0d, 0x95b00c23, "m...." },
  [3117] = { nil, "Leggi l'Etched Sigil e parla con Ayanna Everstride, in cima ad Aldrassil, a Shadowglen.", "Questo sigillo me l'ha dato un messaggero della nostra istruttrice dei cacciatori, Ayanna. Sembra che Ayanna voglia parlarti quando hai un momento. Leggilo e poi portaglielo.", "Sei <arrivato/arrivata>, e non troppo presto, {name}. <Benvenuto/Benvenuta> a Shadowglen.\n\nSpero che il mio sigillo ti abbia <trovato/trovata> in buona salute e di buon umore?\n\nCome ti ho detto, sono qui per addestrarti come <cacciatore/cacciatrice>: a domare le bestie perché ti aiutino in battaglia, a usare l'arco con precisione infallibile, a rispettare le terre che chiamiamo casa e anche le terre al di là.", "Man mano che impari ciò che Shadowglen ha da insegnarti, vieni a trovarmi: potrò aiutarti a capire meglio il tuo ruolo di cacciatore e ciò di cui sei capace.\n\nSono tempi pericolosi, {name}: non dare per scontata l'abilità dei tuoi animali. In questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Vai con Elune e torna di nuovo da me.", nil, 0xd81ae928, 0xec30768a, 0x5c32ead3, 0x1a49e722, "m...." },
  [3118] = { nil, "Leggi l'Encrypted Sigil e parla con Frahun Shadewhisper, a Shadowglen.", "Questo sigillo me l'ha dato un messaggero del nostro istruttore dei ladri, Frahun. Sembra che Frahun voglia parlarti quando hai un momento. Leggilo e poi portaglielo.", "Salve, {name}. Sono contento che tu mi abbia trovato. Pensavo che ti fossi <perso/persa> per strada.\n\nA Shadowglen non è successo niente di nuovo da quando ti ho mandato il mio sigillo, ma lascio a te raccogliere le informazioni. Se vuoi, parla con le altre persone intorno ad Aldrassil.", "Fino ad allora, sappi che c'è bisogno della nostra gente più che mai, in questi tempi incerti. La pace con le altre razze può crollare da un momento all'altro, e si parla molto di membri della Horde che cercano di seminare ancora più diffidenza. Ricordalo.\n\nMan mano che acquisti potere e ti senti più <preparato/preparata>, torna qui da me e vedrò di darti un po' di addestramento. È importante che tu sappia maneggiare l'arma che preferisci, tra le altre cose.", nil, 0x0f31aa64, 0x6d5e7cd1, 0x042e42d6, 0x1de17785, "m...." },
  [3119] = { nil, "Leggi l'Hallowed Sigil e parla con Shanda, ad Aldrassil.", "Questo sigillo me l'ha dato un messaggero della nostra istruttrice dei sacerdoti, Shanda. Sembra che Shanda voglia parlarti quando hai un momento. Leggilo e poi portaglielo.", "Mi fa piacere vedere che sei <arrivato/arrivata> così in fretta, {name}. <Benvenuto/Benvenuta>.\n\nCome probabilmente avrai sentito, tutta Teldrassil è in fermento per l'andirivieni dei viaggiatori. Persino ai membri dell'Alliance è stato concesso l'accesso ai rami di Teldrassil per incontrare altri Kaldorei che si preparano alle avventure future.", "Per ora non preoccuparti del mondo sotto Teldrassil. Ci sarà tempo per quello più avanti. Ora vai a parlare con gli altri a Shadowglen: possono dirti di più sugli eventi accaduti. Aiutali come puoi, e ogni volta che senti di aver bisogno di altro addestramento, torna da me e ti insegnerò ciò che posso.", nil, 0xf53c2a50, 0xca5600b8, 0x1f4e46af, 0x1e10f375, "m...." },
  [3120] = { nil, "Leggi il Verdant Sigil e parla con Mardant Strongoak, nell'albero Aldrassil, a Shadowglen.", "Questo sigillo me l'ha dato un messaggero del nostro istruttore dei druidi, Mardant. Sembra che Mardant voglia parlarti quando hai un momento. Leggilo e poi portaglielo.", "Ah, giovane {class}. Vedo che sei <ansioso/ansiosa> di continuare i tuoi studi. Bene.\n\nMi chiedo, hai già passato molto tempo nell'Emerald Dream? Forse non sei ancora <pronto/pronta> per quello... Col tempo, ne sono certo.\n\nMa fino ad allora, dovremmo parlare di altro.", "Per ora sarò il tuo mentore e la tua guida. È mio dovere insegnarti a interpretare non solo ciò che gli spiriti ci comunicano, ma anche le complessità e i segreti dell'Emerald Dream.\n\nMan mano che impari e cresci in potere, conoscerai meglio la nostra trance del sonno. Ma fino ad allora, torna da me tutte le volte che vuoi e ti insegnerò ciò che posso delle vie della nostra gente.", nil, 0x67426736, 0xaf299504, 0x240343bf, 0x0f1fd4af, "m...." },
  [3121] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [3181] = { "Il corno della bestia", "Porta il Margol's Gigantic Horn a Mountaineer Pebblebitty.", "Il corno gigantesco è pieno di graffi e crepe. Nella superficie ruvida è conficcato uno strano oggetto di metallo.\n\nGuardando meglio, noti che il metallo è in realtà una testa d'ascia spezzata. Sul metallo sono incise queste parole:\n\nProprietà di Mountaineer Pebblebitty.\n\nQuando provi a staccare la testa d'ascia spezzata, va in mille pezzi.\n\nOps!", "No, non aprirò il cancello.", "Cos'hai lì? Un falso, è ovvio!\n\nMi sono trovato faccia a faccia con Margol e so per certo che il suo corno è grande almeno otto volte quello che hai in mano, {name}. Probabilmente l'hai preso a uno stormsnout nei Barrens. No, <signore/signora>, Pebblebitty non si lascia ingannare!", 0x2e5f0c0b, 0xb93db2d2, 0x3392c641, 0x2dfa9f43, 0xe1a41449, ".....", nil, nil, nil, nil, 0x7710ebcd },
  [3182] = { nil, "Porta il Margol's Gigantic Horn a Curator Thorius, a Ironforge.", "Ti aspetti che creda a una storia del genere? Il vero corno avrebbe ancora conficcata nella superficie la mia testa d'ascia spezzata.\n\nSenti, porta quell'evidente falso a Curator Thorius, a Ironforge. Se lui conferma quello che dici, riceverai una prova dell'impresa. Riportami quella prova e ti darò la chiave della Searing Gorge.\n\nMuoviti!", "Ma buongiorno, <giovanotto/signorina>. Ti va una visita al museo?", "Cos'è questo?\n\nOh, cielo, non ci credo! Ti rendi conto di cosa hai qui, {race}? Questo è il corno di Margol the Rager! Margol, la rovina di ogni archeologo che abbia mai messo piede nella Searing Gorge.\n\nPosso tenerlo?", nil, 0x5939f719, 0xb834107c, 0x8e279b3a, 0xe346b32f, "m....", nil, nil, nil, 0xf600fc7f, nil },
  [3361] = { "Il dilemma di un profugo", "Porta il Felix's Box, il Felix's Chest e il Felix's Bucket of Bolts a Felix Whindlebolt, ad Anvilmar.", "Abbiamo cacciato i trogg da Gnomeregan, ma poi è andato tutto terribilmente storto! Ora la nostra casa è completamente irradiata e noi gnomi siamo sparpagliati per tutta Dun Morogh.\n\nNella fretta di sfuggire alle radiazioni, ho perso tutti i miei effetti personali e i miei attrezzi. Sono stati i troll a prenderli. Mi hanno rubato il baule, la scatola e il secchio di bulloni! Li hanno portati nei loro accampamenti a sud-ovest di Anvilmar.\n\nNon sono un avventuriero: potresti trovare le mie cose e portarmele qui, per favore?", "Santo cielo, {name}, questa città non è adatta a quelli come me. Qui ci sono tante creature schifose quante ce n'erano a Gnomeregan prima dell'incidente!\n\nHai le mie cose? Se no, chissà cosa ne avranno fatto ormai i troll...", "Evviva, li hai trovati! Sei proprio <un/una> <salvatore/salvatrice>, amico mio. Tieni, non è molto, ma è qualcosa per il disturbo che ti ho dato! Grazie!", 0x71d49aac, 0x8c5c5442, 0x7b36eefc, 0xe6a8fff5, 0x6f038cb6, "....." },
  [3364] = { "Consegna di Scalding Mornbrew", "Porta una Scalding Mornbrew a Durnan Furcutter, dentro Anvilmar, prima che si raffreddi fra cinque minuti!", "Accidenti! Dovevo portare questa deliziosa scalding mornbrew a Durnan Furcutter, dentro Anvilmar, già da un pezzo, ma prima ho dovuto consegnarne una qui a Grelin. Non arriverò mai ad Anvilmar prima che si raffreddi!\n\nSembri veloce. Forse tu ce la fai. Questa tazza resterà calda solo per altri cinque minuti, e Durnan non ha ordinato una mornbrew \"fredda\", quindi muoviti. Anvilmar è a nord-est, un insediamento scavato nella montagna.\n\nGrazie, {name}, e non dimenticare di riportarmi il boccale!", "Sì, sono Durnan Furcutter. Hai qualcosa per me?", "Ah bene, questa sì che ci voleva. Permettimi una piccola pausa mentre mi godo questa scalding mornbrew!", 0xf0284895, 0x5506e41b, 0xbce4688b, 0x65bfe9d2, 0xd3b1def7, "....." },
  [3365] = { "Riporta il boccale", "Restituisci il Nori's Mug a Nori Pridedrift.", "Questa sì che ci voleva! Niente di meglio di una mornbrew bollente, anzi, scottante, in una fredda giornata d'inverno per scaldarti l'anima.\n\nEcco qua, {name}: fammi il favore di riportare questo boccale vuoto a Nori, va bene?", "Confido che la scalding mornbrew sia arrivata in tempo a Durnan! Ti sei <ricordato/ricordata> di riportarmi il boccale?", "Eccellente, {name}! Ti stupiresti di quanti corrieri incontro che si dimenticano una cosa semplice come riportare il boccale. I boccali non crescono sugli alberi, o almeno così mi dicono!\n\nEcco qualcosa per il disturbo. Grazie ancora per il tuo aiuto.", 0x8db5a5c3, 0x1075f009, 0x2d2a6b06, 0x795e536d, 0x3d3438fe, "....." },
  [3366] = { nil, "Recati a Ratchet per scoprire il significato del Nightmare Shard.", "Il frammento è di un verde brillante e, sebbene solido, sotto la superficie sembra vorticare del fumo. Non puoi fare a meno di fissare le profondità del cristallo; al tempo stesso, sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se qualcuno a Ratchet può dirti di più su questo strano frammento.", nil, nil, nil, 0xa0c652c0, 0xf1eddfb4, nil, nil, "m..mm" },
  [3369] = { "Negli incubi", nil, nil, "Posso aiutarti in qualcosa?", nil, 0x768d8fac, nil, nil, 0x42e8d794, nil, ".mm.m" },
  [3370] = { "Negli incubi", "Porta il Nightmare Shard a Mathrengyl Bearwalker, a Darnassus.", "Questo frammento custodisce grandi segreti: è l'essenza pura dell'Emerald Dream. Ma ciò che vedo in questo frammento non è un sogno; una visione del genere la si chiamerebbe incubo.\n\nNon voglio allarmarti, {name}, ma credo sia meglio che tu consegni questo frammento nelle mani di un druido saggio il prima possibile...\n\nÈ Mathrengyl Bearwalker, del Cenarion Circle, che devi trovare. Va' a Darnassus. Non posso dire altro.", "Posso aiutarti in qualcosa?", "Ti ha mandato Falla? Bene, vediamo questo frammento di cui dici che era così restia a parlare...\n\n<Mathrengyl scruta nel frammento>\n\nOh... non avevo... Beh.\n\n{name}, grazie per avermelo consegnato. Ti consiglio però di non parlare di cose del genere. Sono questioni di cui devono occuparsi soltanto i druidi del Cenarion.\n\nDiciamo solo che nell'Emerald Dream le cose non sono come pensavamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", 0x768d8fac, 0x92596199, 0x891baadf, 0x42e8d794, 0x1d9fadb2, "....." },
  [3519] = { "Un amico nel bisogno", "Parla con Dirania Silvershine, a Shadowglen.", "Ughhh... Mi ha morso malamente un ragno di nome Githyiss the Vile mentre esploravo la caverna dei ragni qui vicino. Sono sicuro di essere stato avvelenato gravemente; devi aiutarmi.\n\nTi prego, avvisa Dirania Silvershine. Lei saprà aiutarmi.\n\nPresto... mi gira così tanto la testa...", nil, "Oh, cielo; mi chiedevo perché oggi non avessi ancora visto Iverron. E l'ho sempre avvertito di quei ragni...", 0x14600625, 0xd73f79e1, 0x6dca0a7e, nil, 0xcf23564b, "...m." },
  [3521] = { nil, "Raccogli 7 Hyacinth Mushrooms, 4 Moonpetal Lilies e 1 Webwood Ichor per Dirania Silveshine, a Shadowglen.", "Forse possiamo aiutare Iverron: conosco un antidoto che dovrebbe funzionare contro il veleno. Ma prima di prepararlo mi servono alcuni ingredienti.\n\nMi servono degli Hyacinth Mushrooms. Crescono sotto gli alberi, oppure puoi prenderli dai grell a sud di qui: sembra che ne vadano matti. Mi servono anche dei Moonpetal Lilies, che crescono solo intorno agli specchi d'acqua.\n\nL'ultimo ingrediente potrebbe essere il più difficile. Raccogli del Webwood Ichor proprio dai ragni che hanno avvelenato Iverron.", "Ti prego, raccogli gli ingredienti, {name}. Iverron ha bisogno del nostro aiuto.", "Grazie a Elune hai raccolto questi ingredienti così in fretta!\n\nTra un momento avrò pronto l'antidoto.", nil, 0x12503cdc, 0x32bb4179, 0xd4e56d7d, 0xbaa1ea59, "m...." },
  [3522] = { nil, "Porta l'Iverron's Antidote a Iverron prima che scada il tempo. Iverron si trova vicino alla caverna a nord.", "L'antidoto è pronto, {name}. Ti prego, fai in modo che Iverron lo beva.\n\nC'è una cosa che devi sapere: l'antidoto resta efficace solo per 5 minuti. Devi portarglielo in tempo.\n\nChe la velocità sia con te, {name}.", "Oh... {name}, sono così felice che tu sia <tornato/tornata>.", "Cos'è questo, {name}?\n\nOh, sapevo che Dirania avrebbe saputo aiutarmi!\n\n<Iverron beve l'antidoto.>\n\nFinisco sempre nei guai e Dirania, be', riesce sempre a tirarmene fuori.\n\nMi sento molto meglio, ma credo che resterò seduto qui ancora un po', finché non mi sarò ripreso del tutto. Be', questo, e speravo che mi apriresti la strada tra quei feroci ragni Webwood...", nil, 0x19c81d7f, 0x9296895f, 0x4cd0a6af, 0xc1dde192, "m...." },
  [3524] = { "Portati a riva", "Recupera le Sea Creature Bones dalla creatura marina spiaggiata appena a sud di Auberdine, poi tornaci da Gwennyth Bly'Leggonde, ad Auberdine.", "Si sa che maestose creature marine si gettano sulla costa di Darkshore e restano spiaggiate finché non muoiono. Ultimamente queste bestie arrivano a riva in numero sempre maggiore. Il Temple of the Moon mi ha mandata qui a indagare, ma la presenza dei murloc lungo l'acqua mi rende difficili le ricerche.\n\nAppena a sud di Auberdine c'è una creatura gigantesca arenata, circondata dai luridi murloc Greymist. Potresti andare lì e recuperare delle ossa della creatura per i nostri studi?", "Solo di recente queste creature hanno cominciato ad arenarsi sulla costa di Darkshore in numero così allarmante. Non posso fare a meno di pensare che sia un cattivo presagio. Recuperare un campione delle ossa di quella creatura a sud aiuterebbe noi di Darnassus a valutare la situazione!", "Spero che i murloc non ti abbiano dato troppi problemi nel raccoglierlo per noi! Mi assicurerò che parta con il prossimo ippogrifo per Darnassus. Il Temple of the Moon mi ha dato dei fondi da distribuire per l'aiuto ricevuto: accettane un po' con i nostri ringraziamenti.\n\nIl tuo successo qui mi spinge a offrirti la possibilità di aiutare ancora il Temple of the Moon, se ti interessa...", 0x8079e34a, 0xdf94400b, 0xdd2f6ea9, 0xb30873ce, 0x899e5ad6, "....." },
  [3526] = { "Ingegneria goblin", "Se vuoi saperne di più sulla Goblin Engineering, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", "L'ingegneria di livello esperto si divide in due discipline distinte: gnomesca e goblin. Chiaramente l'ingegneria goblin è la scelta di tutti gli ingegneri geniali. Impara a dominare il mondo attraverso l'uso giudizioso di esplosivi potenti e congegni fantastici!\n\n{name}, leggi questo manuale. Se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'adesione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Fiuto le nuove reclute come fiuto un'ottima polvere esplosiva: da un miglio di distanza. Sei <venuto/venuta> a imparare la maestria dell'esplosione?", "Ebbene, {name}, sei <stato/stata> <saggio/saggia> a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa irradiata di Gnomeregan ne sono la prova. Ma ci vogliono una mente forte e una mano ferma (e sottolineo ferma) per padroneggiare la disciplina della Goblin Engineering.\n\nTieni le orecchie aperte, {name}, e potresti imparare qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x31040b00, 0x21f4153d, 0xad63c1bf, "....." },
  [3629] = { "Ingegneria goblin", "Se vuoi saperne di più sulla Goblin Engineering, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", "L'ingegneria di livello esperto si divide in due discipline distinte: gnomesca e goblin. Cito l'ingegneria goblin solo perché sono un istruttore onesto. A loro piace costruire cose che esplodono, e raramente si preoccupano di cosa si trova sulla traiettoria, nemmeno di se stessi.\n\n{name}, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'adesione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Fiuto le nuove reclute come fiuto un'ottima polvere esplosiva: da un miglio di distanza. Sei <venuto/venuta> a imparare la maestria dell'esplosione?", "Ebbene, {name}, sei <stato/stata> <saggio/saggia> a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa irradiata di Gnomeregan ne sono la prova. Ma ci vogliono una mente forte e una mano ferma (e sottolineo ferma) per padroneggiare la disciplina della Goblin Engineering.\n\nTieni le orecchie aperte, {name}, e potresti imparare qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x52e16ce5, 0x21f4153d, 0xad63c1bf, "....." },
  [3630] = { "Ingegneria gnomesca", "Se vuoi saperne di più sulla Gnome Engineering, porta il Manual of Engineering Disciplines al Tinkmaster Overspark, a Ironforge.", "L'ingegneria di livello esperto si divide in due discipline: gnomesca e goblin. L'ingegneria gnomesca è di gran lunga la migliore delle due! Si tratta di costruire meravigliosi congegni e dispositivi che rendono la vita migliore!\n\n{name}, leggi questo manuale. Se vuoi imparare di più sull'ingegneria gnomesca, porta quel manuale al Tinkmaster Overspark, a Ironforge. Ricorda: l'adesione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di essere <sicuro/sicura> prima di completare il suo compito!", "Sì, sì, di quali tue esigenze posso occuparmi oggi? Evidentemente ho tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", "Ah, un giovane ingegnere interessato a seguire l'unica, vera disciplina dell'ingegneria! Beh, perdona il mio melodramma, amico. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando un altro ingegnere risponde allo squillo della vera ingegneria!", 0x963c40b5, 0xab72bd39, 0xf53fb9a4, 0xc8d72920, 0x23d1ca8c, "....." },
  [3631] = { "Evocare il Felsteed", nil, nil, nil, "Quindi hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se ti saresti mai <fatto/fatta> vivo. Ho detto loro che non c'era dubbio. Quando si tratta di potere, ne sei <attratto/attratta> come una falena dalla fiamma.", 0x5220fbc8, nil, nil, nil, 0x23773eba, ".mmm." },
  [3632] = { "Ingegneria gnomesca", "Se vuoi saperne di più sulla Gnome Engineering, porta il Manual of Engineering Disciplines al Tinkmaster Overspark, a Ironforge.", nil, "Sì, sì, di quali tue esigenze posso occuparmi oggi? Evidentemente ho tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", "Ah, un giovane ingegnere interessato a seguire l'unica, vera disciplina dell'ingegneria! Beh, perdona il mio melodramma, amico. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando un altro ingegnere risponde allo squillo della vera ingegneria!", 0x963c40b5, 0xab72bd39, nil, 0xc8d72920, 0x23d1ca8c, "..m.." },
  [3633] = { "Ingegneria goblin", "Se vuoi saperne di più sulla Goblin Engineering, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", "L'ingegneria di livello esperto si divide in due discipline distinte: gnomesca e goblin. Chiaramente l'ingegneria goblin è la scelta di tutti gli ingegneri geniali. Impara a dominare il mondo attraverso l'uso giudizioso di esplosivi potenti e congegni fantastici!\n\n{name}, leggi questo manuale. Se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'adesione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Fiuto le nuove reclute come fiuto un'ottima polvere esplosiva: da un miglio di distanza. Sei <venuto/venuta> a imparare la maestria dell'esplosione?", "Ebbene, {name}, sei <stato/stata> <saggio/saggia> a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa irradiata di Gnomeregan ne sono la prova. Ma ci vogliono una mente forte e una mano ferma (e sottolineo ferma) per padroneggiare la disciplina della Goblin Engineering.\n\nTieni le orecchie aperte, {name}, e potresti imparare qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x31040b00, 0x21f4153d, 0xad63c1bf, "....." },
  [3634] = { "Ingegneria gnomesca", "Se vuoi saperne di più sulla Gnome Engineering, porta il Manual of Engineering Disciplines al Tinkmaster Overspark, a Ironforge.", "L'ingegneria di livello esperto si divide in due discipline: gnomesca e goblin. Anche se secondo me è uno spreco, dovresti conoscere la specializzazione gnomesca. Creano oggetti e congegni che pretendono di cambiare il mondo, ma raramente funzionano.\n\n{name}, leggi questo manuale. Se vuoi imparare a fare fermacarte di metallo, porta quel manuale al Tinkmaster Overspark, a Ironforge. Ricorda: l'adesione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di essere <sicuro/sicura> prima di completare il suo compito!", "Sì, sì, di quali tue esigenze posso occuparmi oggi? Evidentemente ho tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", "Ah, un giovane ingegnere interessato a seguire l'unica, vera disciplina dell'ingegneria! Beh, perdona il mio melodramma, amico. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando un altro ingegnere risponde allo squillo della vera ingegneria!", 0x963c40b5, 0xab72bd39, 0xc301270e, 0xc8d72920, 0x23d1ca8c, "....." },
  [3635] = { "Ingegneria gnomesca", nil, nil, nil, nil, 0x963c40b5, nil, nil, nil, nil, ".mmmm" },
  [3636] = { "Portare la Luce", "L'Archbishop Bendictus vuole che tu uccida Amnennar the Coldbringer, a Razorfen Downs.", "La Scourge è una minaccia costante per l'Alliance, cosa che sono certo tu sappia benissimo. Di recente abbiamo fatto scoperte molto particolari, {name}.\n\nNelle Barrens si trova un orribile groviglio di rovi chiamato Razorfen Downs. Se un tempo era la dimora di semplici quilboar, ora è chiaro che è stato stretto un patto con la Scourge, creando creature molto peggiori... Ora sono governati dal lich Amnennar the Coldbringer.\n\nSchierati con la Luce, {name}; poni fine a questa unione malvagia.", "Amnennar deve essere sradicato. Va', in fretta.", "Grazie, {name}. Ora la Scourge ci penserà due volte prima di provare di nuovo a rinforzare i suoi ranghi.\n\nChe la Luce ti benedica.", 0x15219363, 0x58355ea6, 0xf1d2ffc7, 0x30367c57, 0xaa15e714, "....." },
  [3637] = { "Ingegneria gnomesca", nil, nil, nil, nil, 0x963c40b5, nil, nil, nil, nil, ".mmmm" },
  [3661] = { "Favoriti di Elune?", "Raccogli 15 Wildkin Feathers negli Hinterlands per Erelas Ambersky, a Rut'theran Village.", "I wildkin sono creature piuttosto imprevedibili, {name}. Capaci di incredibile dolcezza, queste creature mostrano una ferocia estrema se qualcosa che ritengono importante è minacciato.\n\nSi dice che queste bestie siano state create da Elune, e mi interessa scoprire se sia davvero così.\n\nDi recente ho sentito parlare di una popolazione di wildkin che vive negli Hinterlands: Vicious, Primitive e Savage Owlbeasts. Si trovano tra la fauna del posto. Mi raccoglieresti qualche Wildkin Feathers?", "Cerca di evitarli, se puoi, {name}. I wildkin potrebbero scambiare il tuo interesse per l'intenzione di far loro del male...", "Grazie per avermele portate, {name}.\n\nCosa hai scoperto sui wildkin?\n\nForse queste piume ci diranno di più. Mostri feroci o semplicemente animali sviati? Un giorno vorrei conoscere la verità...\n\nContinuerò le mie ricerche: ti prego, torna a parlarmi tra un po' di tempo.", 0xc37a4269, 0xcccfc461, 0x07d63186, 0x6980b3e3, 0x9787a159, "....." },
  [3741] = { nil, "Trova la Hilary's Necklace e riportala a Hilary, a Lakeshire.", "La mia amica Hilary ha perso la sua collana, e non riusciamo a trovarla. Abbiamo pescato qui tutto il giorno e abbiamo già cercato qui intorno. L'unica cosa che mi viene in mente è che sia caduta nel lago. I nostri genitori non vogliono che facciamo il bagno nel lago... la mia mamma dice che sott'acqua ci sono cose cattive, ma tu non sembri avere paura delle cose cattive.\n\nPotresti trovarla per lei, per favore?", "Ciao. Mi manca la mia collana. Me l'ha regalata il mio papà. Papà dice che nel lago ci sono i mostri. Hai picchiato qualche mostro?", "Grazie per aver trovato la mia collana, <signor/signora> {class}... sei tanto gentile! Ti ringrazia anche il mio gattino, vero Effsee?", nil, 0x56803c15, 0xf3c09303, 0xe8736a32, 0x7a3fe990, "m....", nil, nil, nil, nil, 0xed8e927e },
  [3763] = { "Aiutare Arch Druid Staghelm", "Parla con Arch Druid Fandral Staghelm, a Darnassus.", "Scusami {class}, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Arch Druid Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui nel Cenarion Enclave, a Darnassus.", nil, "Bene, {class}... visto che ti è stato detto che guido io stesso questa ricerca, ovviamente sei <venuto/venuta> più in fretta che potevi.\n\nOra che sei qui, fai attenzione la prima volta che ti spiego i dettagli; non ho alcuna voglia di ripetermi.", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3764] = { nil, "Porta 20 campioni di Un'Goro Soil a Jenal, nel Cenarion Enclave di Darnassus.", "Si dice che il terreno dell'Un'Goro Crater sia ricco di potenti qualità magiche. Voglio distinguere i fatti dalle dicerie; vai nelle terre selvagge di Un'Goro e procurati abbastanza campioni di terra di qualità per proseguire i nostri studi.\n\nPotresti pensare che i compiti di raccolta siano al di sotto di te; un simile atteggiamento non ti rende caro né a me né al Cenarion Circle. Porta i campioni a Jenal, che senza dubbio sta perdendo tempo fuori, dietro questo albero: cerca i mucchi di terra. Si occuperà lui della logistica, non io.", "Ah sì, la terra. L'arcidruido vuole venti carichi per avventuriero, e venti carichi avrà. Che chi cospira contro di noi resti indietro!", "Scarica qui il tuo prezioso carico, nobile {class}. Dev'essere stato un bel peso... non diversamente dal peso che porto io, da visionario. Ecco un compenso per il tuo lavoro, come stabilito dall'arcidruido in persona.\n\nArch Druid Staghelm vuole parlarti di nuovo, {name}, ma per il suo prossimo compito ti sarà utile avere una conoscenza da apprendista esperto di Herbalism. Se non la conosci, però, potrai comunque aiutare il Circle!", nil, 0x765896a7, 0x8b6a582c, 0x33b60dd8, 0x132cb099, "m...." },
  [3765] = { "La corruzione all'estero", "Recati da Gershala Nightwhisper, ad Auberdine.", "Stormwind: che centro brulicante di attività.\n\nHo viaggiato da lontano per cercare aiuto. Si sente spesso dire che coraggiosi avventurieri percorrono le strade di questa città.\n\nMio fratello, Gershala, ha bisogno di assistenza a Darkshore. Vive nella città costiera di Auberdine.\n\nIl viaggio è lungo ed epico. È per questo che chiedo l'aiuto di un {class} di grande esperienza come te.", nil, "Ah, quindi ti ha mandato mio fratello, Argos? Immagino che tu sia <stanco/stanca> per il viaggio. Ma abbiamo molto di cui parlare.", 0xba7186ed, 0xd3d2f1f5, 0x698b9ad9, nil, 0xb83a2954, "...m." },
  [3781] = { "Ricerche sul Morrowgrain", "Porta l'Arch Druid's Seed Voucher a Mathrengyl Bearwalker, nel Cenarion Enclave di Darnassus.", "Con quello che chiamiamo Evergreen Pouch abbiamo coltivato semi di Tharlendris nel terreno dell'Un'Goro Crater. Questi semi danno vita a una serie casuale di erbe potenti. Uno dei risultati è il morrowgrain, un'erba misteriosa di cui sappiamo poco; intendo svelare questo mistero.\n\nPorta questo a Mathrengyl, al piano di sotto, e ti darà dei semi per cominciare. Se li finisci, dovrai comprarne altri da lui.", "Pace e serenità a te, amico. Sei qui per affari dell'arcidruido in persona, vero?", "Sì, questo buono vale venti pacchetti di semi. Se li finisci, ne abbiamo altri da fornire. Purtroppo però i semi di Tharlendris sono piuttosto costosi da produrre in quantità. Per questo il Cenarion Circle chiede a chi ci aiuta di contribuire a coprire una parte del costo.\n\nChi torna con il morrowgrain scopre che la ricompensa offerta dall'arcidruido compensa ampiamente il costo.", 0x5cd3af85, 0xe666d2f2, 0x786c2f34, 0x2c0b9166, 0xd45cbd8d, "....." },
  [3782] = { "Ricerche sul Morrowgrain", nil, nil, nil, nil, 0x5cd3af85, nil, nil, nil, nil, ".mmmm" },
  [3785] = { "Ricerche sul Morrowgrain", "Usa un Evergreen Pouch con un Packet of Tharlendis Seeds e due campioni di Un'Goro Soil per provare a coltivare dei campioni di Morrowgrain.\n\nPorta 10 Morrowgrain a Mathrengyl Bearwalker, a Darnassus.", "Ecco l'Evergreen Pouch con cui dovrai usare i semi di Tharlendis. Ti serve anche avere a portata di mano dei campioni di Un'Goro Soil da usare come fertilizzante per i semi. Quando hai tutto, usa la sacca: al resto penserà lei.\n\nQuando avrai abbastanza Morrowgrain, portamelo qui nell'enclave. Ti prego, non disturbare l'arcidruido; è un uomo molto impegnato, e non ha bisogno di essere disturbato ogni volta che qualcuno torna con un'altra partita di morrowgrain!", "Allora {name}, hai coltivato un po' di Morrowgrain per le importanti ricerche dell'arcidruido? Il lavoro che sta facendo per il Cenarion Circle è molto importante, e il tuo aiuto non passerà inosservato!", "Ben fatto {name}, li darò di sicuro all'arcidruido in persona quando gli serviranno. Nel frattempo, ti prego, accetta questo come segno della riconoscenza del Cenarion Circle.\n\nIl nostro bisogno di morrowgrain è continuo; se vuoi continuare ad aiutarci, torna da me quando avrai coltivato altro morrowgrain per noi.", 0x5cd3af85, 0xcfe1f98d, 0x81f87e3a, 0x859e04b5, 0xbb7b95ba, "....." },
  [3786] = { "Ricerche sul Morrowgrain", nil, nil, nil, nil, 0x5cd3af85, nil, nil, nil, nil, ".mmmm" },
  [3787] = { "La richiesta di Jonespyre", "Parla con Quintis Jonespyre, a Feathermoon Stronghold.", "Scusami, amico...\n\nUn mio collega vorrebbe parlarti delle ricerche che stai svolgendo insieme al Cenarion Circle. È un druido di nome Quintis Jonespyre e risiede a Feathermoon Stronghold, a Feralas. Vorrebbe consultarsi con te sul morrowgrain... e gradirebbe molto che la nostra conversazione non giungesse alle orecchie dell'Arch Druid.\n\nSe ti interessa, parla con lui; senza dubbio, tutto ti sarà rivelato.", nil, "Grazie di essere <venuto/venuta>, <stanco/stanca> <viaggiatore/viaggiatrice>! Permettimi di presentarmi: sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. I miei colleghi (la General Shandris Feathermoon e il Protectorate, forse ne hai sentito parlare) e io volevamo parlarti del lavoro che stai svolgendo per Fandral Staghelm a Darnassus.\n\nPrima di andare oltre, vorrei chiederti che la nostra conversazione resti tra noi. Se per te non è un problema, possiamo procedere.", 0xb0b67119, 0xf2782e63, 0xaf54904d, nil, 0x8fcfd489, "...m." },
  [3788] = { "La richiesta di Jonespyre", "Parla con Quintis Jonespyre, a Feathermoon Stronghold.", nil, nil, "Grazie di essere <venuto/venuta>, <stanco/stanca> <viaggiatore/viaggiatrice>! Permettimi di presentarmi: sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. I miei colleghi (la General Shandris Feathermoon e il Protectorate, forse ne hai sentito parlare) e io volevamo parlarti del lavoro che stai svolgendo per Fandral Staghelm a Darnassus.\n\nPrima di andare oltre, vorrei chiederti che la nostra conversazione resti tra noi. Se per te non è un problema, possiamo procedere.", 0xb0b67119, 0xf2782e63, nil, nil, 0x8fcfd489, "..mm." },
  [3789] = { "Aiutare Arch Druid Staghelm", "Parla con Arch Druid Fandral Staghelm, a Darnassus.", "Scusami {class}, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Arch Druid Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui nel Cenarion Enclave, a Darnassus.", nil, "Bene, {class}... visto che ti è stato detto che guido io stesso questa ricerca, ovviamente sei <venuto/venuta> più in fretta che potevi.\n\nOra che sei qui, fai attenzione la prima volta che ti spiego i dettagli; non ho alcuna voglia di ripetermi.", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3790] = { "Aiutare Arch Druid Staghelm", "Parla con Arch Druid Fandral Staghelm, a Darnassus.", "Scusami {class}, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Arch Druid Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui nel Cenarion Enclave, a Darnassus.", nil, "Bene, {class}... visto che ti è stato detto che guido io stesso questa ricerca, ovviamente sei <venuto/venuta> più in fretta che potevi.\n\nOra che sei qui, fai attenzione la prima volta che ti spiego i dettagli; non ho alcuna voglia di ripetermi.", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3861] = { "COCCODÈ!", "Trova del Special Chicken Feed e torna dalla gallina che hai fatto amica. Quando l'avrai trovato, esulta davanti a lei (/cheer) prima di provare a darle lo Special Chicken Feed.", "\"Coccodè... coccodè... coccodè... COCCODÈÈ!\n\nCoccodè... coccodè... coccodè.\"\n\nLa gallina ti guarda e poi comincia a grattare il terreno con le zampe. Sembra che stia scrivendo una parola, ma non sei <sicuro/sicura> di cosa sia. Potrebbe essere... S-A-L-D-E-A-N? Prima che tu possa chiederlo, la gallina si volta e torna alle sue faccende.", "La gallina ti fissa con occhi scuri e freddi. Ti aspetta, affamata.\n\n\"COCCODÈÈÈ!\n\nCoccodè... coccodè... coccodè.\"", "\"COCCODÈ!!!\"\n\nLa gallina comincia a ingozzarsi del mangime che le hai messo davanti.\n\nDopo un momento, la gallina si guarda intorno, spaventata. Si agita a disagio avanti e indietro. Che sia incinta? Forse è meglio controllare sotto di lei.", 0x15276154, 0x72531b26, 0xa6190e7e, 0x6aec8435, 0x76e1a259, "....." },
  [3903] = { nil, "Parla con Milly Osworth.", "Hai dimostrato di essere affidabile come {class}, {name}. Affidabile, e senza paura di sporcarti le mani, eh?\n\nHo un'amica, Milly Osworth, che è nei guai. È dall'altra parte dell'abbazia con il suo carro, vicino alla stalla. Sono sicuro che un paio di mani come le tue le farebbero comodo.", nil, "Oh, è stato Deputy Willem a dirti di parlare con me? È un uomo coraggioso e sempre pronto ad aiutare, ma i suoi doveri lo tengono bloccato alla Northshire Abbey e temo che il problema che ho oggi sia al di là delle sue possibilità.\n\nForse puoi aiutarmi tu?", nil, 0xf258ab38, 0x7ad88966, nil, 0xcb7f07d4, "m..m." },
  [3904] = { nil, "Porta 8 casse di Milly's Harvest a Milly Osworth, alla Northshire Abbey.", "Una banda di briganti, i Defias, si è insediata nei Northshire Vineyards mentre facevo la vendemmia! L'ho riferito alle guardie di Northshire e mi hanno assicurato che se ne sarebbero occupate, ma... temo per il mio raccolto d'uva! Se non me la rubano i Defias, ho paura che la calpestino le guardie mentre scacciano quei delinquenti.\n\nTi prego, devi aiutarmi! Ho raccolto quasi tutta l'uva nei secchi, ma li ho lasciati nei vigneti a sud-est.\n\nPortami quelle casse! Salva il mio raccolto!", "Hai il mio raccolto, {name}?", "Oh, grazie, {name}! Hai salvato il mio raccolto! E spero che tu abbia fatto capire a qualcuno di quei Defias che qui non possono creare guai.\n\nSaremo anche a corto di guardie di questi tempi, ma siamo fortunati ad avere eroi come te a proteggerci!", nil, 0x92647f37, 0x0fa99512, 0x44af6d31, 0xbc754155, "m...." },
  [3905] = { nil, "Porta il Grape Manifest a Brother Neals, nella Northshire Abbey.", "Ora che il mio raccolto è salvo, porta questo Grape Manifest a Brother Neals. Gestisce le scorte di cibo e bevande di Northshire, e sono certa che sarà felicissimo di sapere che ha dell'uva fresca.\n\nTroverai Brother Neals nell'abbazia, nel campanile... dove gli piace assaggiare il suo vino.", "Mi sembri di ottimo umore! Vieni! Siediti e bevi qualcosa!", "Vediamo un po'...\n\nOh, cielo! L'uva di Milly è salva! Quando mi ha detto che i briganti avevano invaso i suoi vigneti stavo quasi per disperare, ma la mia fede nella Luce non ha vacillato!\n\nE grazie al tuo coraggio, ora abbiamo uva per altro vino! Che la Luce ti benedica, {name}, e ti protegga!", nil, 0x54a8efd7, 0x7e4adc7b, 0x920c46b4, 0x8ad49c5d, "m...." },
  [3922] = { nil, "Porta 15 Nugget Slugs a Wenikee Boltbucket, nelle Barrens.", "Voglio riparare questo samophlange, ma per farlo mi serviranno dei materiali. Ho finito i nugget slug da diciassette virgola cinque e me ne serviranno parecchi per il lavoro che mi aspetta.\n\nIl posto più vicino dove trovarli è la Sludge Fen, a est. Di solito la Venture Company li tiene nei suoi secchi degli attrezzi. Va' alla Sludge Fen e guarda nei secchi degli attrezzi che trovi, poi torna da me quando avrai raccolto abbastanza nugget slug.", "Hai i nugget slug, {name}? Ho messo gli occhi su questo samophlange e non vedo l'ora di armeggiarci.", "Ottimo, li hai presi! Ora posso mettermi al lavoro...", nil, 0x60a82d68, 0x9253461d, 0xaa34b2e5, 0x1136f9bf, "m...." },
  [3923] = { nil, "Porta il Broken and Battered Samophlange a Rilli Greasygob, a Orgrimmar.", "Beh, non ha funzionato. Ho messo qualche indicatore in più sul samophlange per misurarne l'integrità strutturale, e segnano un'integrità ai minimi storici. Potrei aggiungere altri quadranti e forse una leva o due per cercare di ripararlo, ma... credo che potrebbe peggiorare ancora le cose.\n\nDovresti portare il samophlange a Rilli Greasygob. Lavorava per la Venture Company: se qualcuno sa come ripararlo, è Rilli.\n\nLo trovi al Nogg's Machine Shop, a Orgrimmar, nella Valley of Honor.", "Occhio alla testa! Non voglio che intralci il mio lavoro!", "Cos'è questo? Ma è un samophlange! Dove hai preso questo affare? Sei <andato/andata> a ficcare il naso nei possedimenti della Venture Company nelle Barrens?\n\nDevi essere molto <coraggioso/coraggiosa>, o molto <stupido/stupida>.", nil, 0x451916dc, 0xf87c0604, 0xe6681672, 0xdb24502b, "m...." },
})
